import { expect, test, uniqueName } from "../../fixtures";

const TEN_MIB = 10 * 1024 * 1024;

test.describe("Upload vendor documents", () => {
  test(
    "A file of exactly 10 MiB is accepted",
    { tag: "@DOC-05" },
    async ({ apiAs }) => {
      // Background: signed in as a member, vendor in status "draft"
      const member = await apiAs("member");
      const createResponse = await member.post("/api/vendors", {
        data: {
          name: uniqueName("DOC05 Vendor"),
          category: "services",
          contact_email: `doc05-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}@vendor.test`,
        },
      });
      expect(createResponse.status()).toBe(201);
      const vendor = (await createResponse.json()) as { id: string; status: string };
      expect(vendor.status).toBe("draft");

      // When: upload a text file of exactly 10 MiB as kind "contract"
      const buffer = Buffer.alloc(TEN_MIB, "a");
      expect(buffer.length).toBe(TEN_MIB);

      const response = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "contract",
          file: {
            name: "contract-10mib.txt",
            mimeType: "text/plain",
            buffer,
          },
        },
      });

      // Then: the response status is 201
      expect(response.status()).toBe(201);
    },
  );
});
